import{_ as n,o as e,c as h,b6 as i}from"./chunks/framework.BUXTSoD9.js";const p=JSON.parse('{"title":"Giới thiệu dự án","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/guide/introduction.md","filePath":"vi-vn/guide/introduction.md"}'),a={name:"vi-vn/guide/introduction.md"};function l(g,t,d,r,c,s){return e(),h("div",null,[...t[0]||(t[0]=[i('<h1 id="gioi-thieu-du-an" tabindex="-1">Giới thiệu dự án <a class="header-anchor" href="#gioi-thieu-du-an" aria-label="Permalink to “Giới thiệu dự án”">​</a></h1><p>Năm 2025 được nhiều người coi là năm khởi đầu của lập trình AI. Ngày càng có nhiều người bắt đầu dùng AI để viết code, nhưng những gì tạo ra thường chỉ dừng lại ở mức đồ chơi -- không biết cách dùng Vibe Coding để tổ chức quy trình phát triển, không biết nên chọn công cụ nào, và càng không rõ từ nguyên mẫu đến khi đưa lên mạng còn thiếu những bước quan trọng nào.</p><p>Chúng tôi áp dụng lộ trình thực chiến <strong>ba giai đoạn tuần tự</strong>: giai đoạn người mới bắt đầu làm quen với lập trình AI thông qua các trò chơi nhỏ, giai đoạn một làm chủ cách làm việc của Vibe Coding và hoàn thành nguyên mẫu ứng dụng Web, giai đoạn hai học phát triển full-stack và triển khai trực tuyến, giai đoạn ba xây dựng ứng dụng phức tạp đa nền tảng.</p><p>Mỗi giai đoạn đều đi kèm với thực chiến dự án hoàn chỉnh, giúp bạn tiến từ đồ chơi đến sản phẩm thực tế trong những thử thách thật, cuối cùng có khả năng <strong>biến bất kỳ ý tưởng nào thành ứng dụng sử dụng được</strong>.</p><p>Chúng tôi tin rằng, khi làm chủ Vibe Coding kết hợp với đào tạo hệ thống, bạn một mình có thể trở thành <strong>nhà phát triển toàn năng kết hợp giữa phát triển front-end/back-end, tích hợp năng lực AI và thiết kế sản phẩm</strong>.</p><p>Dự án này chủ yếu hướng tới ba loại học viên:</p><ul><li><strong>Người mới (người bình thường / phía sản phẩm và vận hành)</strong>: Giúp những người không có nền tảng kỹ thuật và người mới học hiểu được các khái niệm quan trọng, hoàn thành công cụ AI nhỏ hoặc nguyên mẫu sản phẩm đầu tiên.</li><li><strong>Nhà phát triển trung cấp (sinh viên và nhà phát triển có nền tảng nhất định)</strong>: Làm chủ hệ thống vibe coding và phát triển ứng dụng AI nguyên bản.</li><li><strong>Nhà phát triển cấp cao (công ty và startup, mã nguồn mở và nhà phát triển độc lập)</strong>: Hỗ trợ đội ngũ và cá nhân nhanh chóng xây dựng, xác minh và lặp lại ứng dụng AI nguyên bản.</li></ul><h2 id="📖-đieu-huong-noi-dung" tabindex="-1">📖 Điều hướng nội dung <a class="header-anchor" href="#📖-đieu-huong-noi-dung" aria-label="Permalink to “📖 Điều hướng nội dung”">​</a></h2><h3 id="phu-luc-tong-hop" tabindex="-1">Phụ lục tổng hợp <a class="header-anchor" href="#phu-luc-tong-hop" aria-label="Permalink to “Phụ lục tổng hợp”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/vi-vn/appendix/8-artificial-intelligence/ai-capability-dictionary.html">Từ điển năng lực AI: Các khái niệm và thuật ngữ cốt lõi AI phổ biến, giải thích theo kịch bản</a></p><h3 id="so-0-mam-non" tabindex="-1">Số 0, Mầm non <a class="header-anchor" href="#so-0-mam-non" aria-label="Permalink to “Số 0, Mầm non”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/learning-map/">Người mới bắt đầu: Bản đồ học tập</a></td><td style="text-align:left;">Tổng quan lộ trình học tập</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/ai-capabilities-through-games/">Người mới bắt đầu: Kỷ nguyên AI, biết nói là biết lập trình</a></td><td style="text-align:left;">Cảm nhận ban đầu về năng lực lập trình AI thông qua các ví dụ như rắn săn mồi</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="so-1-quan-ly-san-pham-ai" tabindex="-1">Số 1, Quản lý sản phẩm AI <a class="header-anchor" href="#so-1-quan-ly-san-pham-ai" aria-label="Permalink to “Số 1, Quản lý sản phẩm AI”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/introduction-to-ai-ide/">Sơ cấp 2: Làm quen với công cụ AI IDE</a></td><td style="text-align:left;">Học cách sử dụng IDE, làm chủ cấu trúc giao diện và cách gợi ý hiệu quả</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/building-prototype/">Sơ cấp 3: Tự tay tạo nguyên mẫu</a></td><td style="text-align:left;">Vòng lặp hoàn chỉnh từ phân tích sản phẩm, phân tách đến thực hiện nguyên mẫu sản phẩm đa trang</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/integrating-ai-capabilities/">Sơ cấp 4: Thêm năng lực AI cho nguyên mẫu</a></td><td style="text-align:left;">Hiểu và hoàn thành tích hợp API các năng lực AI phổ biến (văn bản, hình ảnh, video)</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/complete-project-practice/">Sơ cấp 5: Thực chiến dự án hoàn chỉnh</a></td><td style="text-align:left;">Mô phỏng kịch bản thực tế, nhận phản hồi người dùng để lặp lại và hoàn thành trình bày dự án (bao gồm bài tập lớn)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="phu-luc" tabindex="-1">Phụ lục <a class="header-anchor" href="#phu-luc" aria-label="Permalink to “Phụ lục”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-a-product-thinking/">Phụ lục A: Bổ sung tư duy sản phẩm</a></td><td style="text-align:left;">Khung tư duy sản phẩm từ đánh giá ý tưởng đến phân tách nhu cầu và MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-b-common-errors/">Phụ lục B: Lỗi phổ biến và giải pháp</a></td><td style="text-align:left;">Các lỗi phổ biến trong vibe coding và phương pháp khắc phục</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-idea-sources/">Phụ lục: Tìm ý tưởng ở đâu</a></td><td style="text-align:left;">Rút ra hướng ngách từ ứng dụng tham khảo, xu hướng và danh sách VC</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-double-diamond/">Phụ lục: Mô hình Double Diamond</a></td><td style="text-align:left;">Hiểu nhịp độ hoàn chỉnh của việc xác định vấn đề trước rồi mới triển khai thiết kế giải pháp</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-jobs-to-be-done/">Phụ lục: Jobs to Be Done</a></td><td style="text-align:left;">Dùng phương pháp JTBD để thấy rõ điều người dùng thực sự muốn hoàn thành</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-1/appendix-mom-test/">Phụ lục: Phương pháp phỏng vấn The Mom Test</a></td><td style="text-align:left;">Phương pháp nghiên cứu xác minh nhu cầu thông qua phỏng vấn người dùng</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="so-2-ky-su-phat-trien-trung-cap" tabindex="-1">Số 2, Kỹ sư phát triển trung cấp <a class="header-anchor" href="#so-2-ky-su-phat-trien-trung-cap" aria-label="Permalink to “Số 2, Kỹ sư phát triển trung cấp”">​</a></h3><h4 id="phan-front-end" tabindex="-1">Phần front-end <a class="header-anchor" href="#phan-front-end" aria-label="Permalink to “Phần front-end”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;">Sử dụng lovart để sản xuất tài liệu</td><td style="text-align:left;">Học cách dùng lovart để tạo hàng loạt tài liệu hình ảnh nhân vật, bối cảnh, v.v., cung cấp nền tảng tài liệu cho thiết kế UI và phát triển front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Figma và MasterGo nhập môn</td><td style="text-align:left;">Dùng công cụ thiết kế để sắp xếp kiến trúc thông tin và cấu trúc trang, tạo nền tảng cho thực hiện front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Xây dựng ứng dụng hiện đại đầu tiên - Thiết kế UI</td><td style="text-align:left;">Dựa trên bản thiết kế hoàn thành giao diện component hóa, thực hiện chuỗi liên kết đầu tiên từ thiết kế đến code</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Tham khảo quy chuẩn thiết kế UI để thiết kế trang và nút</td><td style="text-align:left;">Học cách dùng quy chuẩn thiết kế phổ biến để tổ chức cấu trúc trang, phân cấp nút, và dùng AI để tạo phương án thiết kế</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-2/frontend/hogwarts-portraits/">Cùng làm chân dung Hogwarts</a></td><td style="text-align:left;">Từ 0 đến 1 tạo ứng dụng front-end tích hợp năng lực AI, kết nối thiết kế và phát triển</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="phan-phat-trien-back-end" tabindex="-1">Phần phát triển back-end <a class="header-anchor" href="#phan-phat-trien-back-end" aria-label="Permalink to “Phần phát triển back-end”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;">API là gì</td><td style="text-align:left;">Hiểu giao diện HTTP và mô hình yêu cầu-phản hồi, chuẩn bị cho tích hợp back-end và debug liên thông</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-2/backend/database-supabase/">Từ cơ sở dữ liệu đến Supabase</a></td><td style="text-align:left;">Triển khai cơ sở dữ liệu và API trên Supabase, kết nối mô hình dữ liệu và trang front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Mô hình lớn hỗ trợ viết code giao diện và tài liệu giao diện</td><td style="text-align:left;">Dùng mô hình lớn hỗ trợ tạo tài liệu giao diện và cơ sở dữ liệu, code, thực hiện back-end có thể đọc và kiểm tra</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Quy trình làm việc Git và triển khai Zeabur</td><td style="text-align:left;">Quản lý code trong quy trình Git và triển khai ứng dụng lên Zeabur trực tuyến</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Công cụ phát triển CLI hiện đại</td><td style="text-align:left;">Sử dụng công cụ lập trình AI loại CLI để tăng tốc phát triển và gỡ lỗi, hình thành quy trình làm việc kỹ thuật cá nhân</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Cách tích hợp hệ thống thanh toán như stripe</td><td style="text-align:left;">Tích hợp hệ thống thanh toán, hoàn thành chuỗi thanh toán và quy trình thanh toán cơ bản</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Xây dựng ứng dụng hiện đại đầu tiên - Ứng dụng full-stack</td><td style="text-align:left;">Tổng hợp front-end, back-end và module thanh toán, hoàn thành ứng dụng Web full-stack có thể trực tuyến</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Thư viện component front-end hiện đại + Thực chiến Trae</td><td style="text-align:left;">Sử dụng thư viện component front-end hiện đại và Trae, độc lập hoàn thành sản phẩm hỗ trợ đăng ký và thanh toán</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="phu-luc-nang-luc-ai" tabindex="-1">Phụ lục năng lực AI <a class="header-anchor" href="#phu-luc-nang-luc-ai" aria-label="Permalink to “Phụ lục năng lực AI”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chương</th><th style="text-align:left;">Nội dung chính</th><th style="text-align:left;">Trạng thái</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/vi-vn/stage-2/ai-capabilities/dify-knowledge-base/">Nhập môn Dify và tích hợp kiến thức</a></td><td style="text-align:left;">Dùng Dify Workflow và RAG cơ bản để xây dựng sản phẩm loại công cụ, tạo mẫu cho việc nâng cấp ứng dụng sau này</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Học cách tra cứu từ điển AI và tích hợp API đa phương thức</td><td style="text-align:left;">Học cách tìm mô hình và API phù hợp, và tích hợp năng lực đa phương thức như văn bản, hình ảnh vào sản phẩm</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="so-3-ky-su-phat-trien-cap-cao" tabindex="-1">Số 3, Kỹ sư phát triển cấp cao <a class="header-anchor" href="#so-3-ky-su-phat-trien-cap-cao" aria-label="Permalink to “Số 3, Kỹ sư phát triển cấp cao”">​</a></h3>',24)])])}const u=n(a,[["render",l]]);export{p as __pageData,u as default};
